# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
def hysteresis(x, k, xi, yi, FY, x_lim):
    if x == xi:
        y = yi
    elif x > xi:
        if yi == FY:
            y = flat(x, xi, yi)
        if yi == -FY:
            x_lim = get_x_limit(xi, FY, k)
        if -FY <= yi < FY:
            if x > x_lim:
                y = jump(FY, x_lim)
            else:
                y = walk(x, xi, yi, k)
    elif x < xi:
        if yi == -FY:
            y = flat(x, xi, yi)
        if yi == FY:
            x_lim = get_x_limit(xi, -FY, k)
        if -FY < yi <= FY:
            if x < x_lim:
                y = jump(-FY, x_lim)
            else:
                y = walk(x, xi, yi, k)
    return y, x_lim

def flat(x, xi, yi):
    return yi

def get_x_limit(xi, FY, k):
    x_limit = xi + 2 * FY / k
    return x_limit

def jump(FY, x_limit):
    return FY

def walk(x, xi, yi, k):
    y = k * (x - xi) + yi
    return y

# main function
